const rtdal001555Source0002 = `make_rect <- function(xmin, ymin, xmax, ymax, crs) {
  sf::st_sfc(
    sf::st_polygon(
      list(
        matrix(
          c(xmin, ymin,
            xmax, ymin,
            xmax, ymax,
            xmin, ymax,
            xmin, ymin),
          ncol=2,
          byrow=TRUE))),
    crs=crs)
}`

const rtdal001555Source0003 = `make_circle <- function(x, y, r, crs) {
  suppressWarnings(sf::st_buffer(
    sf::st_sfc(
      sf::st_point(c(x, y)),
      crs=crs),
    r))
}`

const rtdal001555Source0004 = `make_square_raster <- function(vals, crs=default_proj) {
  n <- sqrt(length(vals))

  stopifnot(as.integer(n) == n)

  raster::raster(matrix(vals, nrow=n, byrow=TRUE),
                 xmn=0, xmx=n, ymn=0, ymx=n,
                 crs=crs)
}`

const rtdal001555Source0005 = `make_square_rast <- function(vals, crs=default_proj) {
  n <- sqrt(length(vals))

  stopifnot(as.integer(n) == n)

  x <- terra::rast(nrows = n, ncols = n,
                   xmin=0, xmax=n, ymin=0, ymax=n,
                   crs = gsub("+init=", "", crs, fixed = TRUE))
  terra::values(x) <- vals
  x
}`

