const rtdal001559Source0025 = `test_that('Error thrown if scalar args have length != 1', {
  rast <- make_square_raster(1:100)
  circle <- make_circle(7.5, 5.5, 4, sf::st_crs(rast))

  flags <- c(
    'coverage_area',
    'force_df',
    'full_colnames',
    'include_area',
    'include_cell',
    'include_xy',
    'progress',
    'stack_apply',
    'summarize_df')

  for (flag in flags) {
    base_args <- list(rast, circle)

    for (bad_value in list(logical(), c(TRUE, TRUE), NA)) {
      args <- base_args
      args[[flag]] <- bad_value

      expect_error(
        do.call(exact_extract, args),
        'must be TRUE or FALSE'
      )
    }
  }
})`

