const rtdal001713Source0001 = `"predictSurface.mKrig" <- function(object, gridList=NULL, grid.list=NULL, 
        ynew = NULL,                          
       extrap = FALSE, chull.mask = NA,
       nx = 80, ny = 80,
       xy = c(1,2),  verbose = FALSE,
       XMatGrid=NULL, drop.XMat= FALSE, 
       ZGrid = NULL, drop.Z = NULL, 
      just.fixed=FALSE, 
       fast=FALSE, NNSize=4,
       setupObject=NULL, 
       giveWarnings=FALSE,
       derivative=0, ...) {
  #
  # some temporary code to handle switch to XMat etc.
  if( !is.null( ZGrid)| !is.null(drop.Z)){
    if( !is.null( ZGrid)){ XMatGrid<- ZGrid}
    if(!is.null( drop.Z)){drop.XMat<- drop.Z}
    warning(" ZGrid,  drop.Z  as arguments 
        have been changed to XMatGrid and drop.XMat to be more consistent
        with a spatial model notation. 
        In the future please use these instead. ")
  }
  #
      if( is.null(XMatGrid) & !drop.XMat & (!is.null(object$XMat)) ) {
      stop("Need to specify covariate (XMat) values or set drop.XMat==TRUE")
      }
      if( !is.null(setupObject)& !fast){
        stop("Setup Object only makes sense when fast = TRUE
             (nearest neighbor rapid prediction)")
      }
    
# grid.list is old syntax for fields gridList preferred 
  if (!is.null(grid.list)){ gridList<-  grid.list}
  
  # Try to grab grid from setupObject 
   if (is.null(gridList)& !is.null(setupObject)) {
     gridList<- setupObject$marginInfo$gridList
   }
  
  # create a default grid if it is not passed  
    if (is.null(gridList)) {
    # default is 80X80 grid on first  variables in 1D
    # first two in 2D or greater for > 2D 
    # rest are set to median value of the x's
        gridList <- fields.x.to.grid(object$x, nx = nx, ny = ny, 
            xy = xy)
       
    }
  
  #print( gridList)
# do some checks on XMatgrid and also reshape as a matrix
# rows index grid locations and columns  are the covariates
# (as XMat in predict).
# if XMatGrid is NULL just returns NULL back  ...
    
    xg <- make.surface.grid(gridList)
# NOTE: the predict function called will need to do some internal checks
# whether the evaluation of a large number of grid points (xg)  makes sense.
  if( verbose){
    print( dim( xg))
    print( nrow( xg))
    print( drop.XMat)
    cat("summary of XMatGrid", fill=TRUE)
    print( summary( XMatGrid))
  }
    if( nrow(xg) > 5e5){
      warning("number of grid points is large for exact prediction
              consider approximate prediction using fast==TRUE")
    }
    out<- rep( NA, nrow(xg))  
    
# if extrapolate is FALSE only predict for locations inside convex hull
# (or the range in 1D) 
    
    indexGood <- rep(TRUE, nrow(xg))
    if (!extrap) {
      if (ncol(xg) > 1)
      {
        if (is.na(chull.mask)) {
          chull.mask <- unique.matrix(object$x[, xy])
        }
        indexGood <-
          in.poly(xg[, xy], xp = chull.mask, convex.hull = TRUE)
      }
      else{
        # 1D case
        indexGood <-  xg[, 1] >= min(object$x[, 1]) &
          xg[, 1] <= max(object$x[, 1])
      }
    }
    
    if(!fast){
# here is the heavy lifting 
# need to handle the XMat image covariates separately for fast and not fast. 
    XMat<- unrollXMatGrid( gridList, XMatGrid) 
    out[indexGood] <-  predict.mKrig(object, xnew=xg[indexGood,], ynew=ynew,
                               XMat=XMat[indexGood,], drop.XMat= drop.XMat, 
                               collapseFixedEffect = object$collapseFixedEffect,
                               just.fixed=just.fixed, ...)
  }
  else{
  # rapid approximate method 
  # will always predict  to full grid, note pass through of setup object to avoid redoing
  #
   
    out<- mKrigFastPredict( object,
                          gridList= gridList, 
                          ynew = ynew,
                          derivative = derivative,
                          XMatGrid = XMatGrid, drop.XMat = drop.XMat,
                          NNSize=NNSize, 
                          setupObject= setupObject, 
                          giveWarnings=giveWarnings,
                          ...
                         )
#
# wipe out predictions outside convex hull of observations. 
#
  if(!extrap){
    out[ !indexGood]<- NA
  }
    
  }
#    
# reshape as list with x, y and z components 
#
  out <-  as.surface( xg, out )
  return(out)
}`

